const ACTOR_ID='HiJYKx437rQqU6YMb';
const BUSINESS_TAB='Career Current',HISTORY_TAB='Career History',RUN_TAB='Career Runs',LOCK_TAB='_CAREER_WORKFLOW_LOCK';
const MAX_EXISTING=5000,MAX_DATASET=1000;
const BUSINESS_HEADERS=['jobKey','jobId','title','companyName','companyDomain','source','jobUrl','applyUrl','location','remote','employmentType','postedAt','firstSeenAt','lastSeenAt','firstSeenRunId','lastRunId','firstObservationType','companyUrl'];
const HISTORY_HEADERS=['observationKey','runId','jobKey','jobId','title','companyName','location','remote','postedAt','observedAt','observationType','jobUrl','companyUrl'];
const RUN_HEADERS=['runId','status','companyUrl','maxJobs','startedAt','finishedAt','datasetId','rowsRead','rowsRejected','baselineJobs','newJobs','rowsUpdated','historyAdded','replayed','maxChargeUsd','buildNumber','executionId','notes'];
function config(input){
 const c={...input};c.companyUrl=String(input.companyUrl??'').trim().replace(/\/$/,'');c.spreadsheetId=String(input.spreadsheetId??'').trim();c.resumeRunId=String(input.resumeRunId??'').trim();c.maxJobs=Number(input.maxJobs);c.maxChargeUsd=Number(input.maxChargeUsd);
 const match=c.companyUrl.match(/^https:\/\/([a-z0-9.-]+\.[a-z]{2,})(?:\/[^\s?#]*)?$/i);
 if(!match||/^(?:localhost|127\.|10\.|192\.168\.|172\.)/i.test(match[1])||c.companyUrl.length>300)throw new Error('Use one public HTTPS URL without credentials, query, or fragment.');
 if(!/^[A-Za-z0-9_-]{20,100}$/.test(c.spreadsheetId))throw new Error('Paste a Google spreadsheet ID before paid work.');
 if(c.resumeRunId&&!/^[A-Za-z0-9]{17}$/.test(c.resumeRunId))throw new Error('resumeRunId must be a 17-character Apify run ID.');
 if(!Number.isInteger(c.maxJobs)||c.maxJobs<1||c.maxJobs>100)throw new Error('maxJobs must be 1–100.');
 if(!Number.isFinite(c.maxChargeUsd)||c.maxChargeUsd<0.01||c.maxChargeUsd>1)throw new Error('maxChargeUsd must be $0.01–$1.');
 return c;
}
function actorInput(c){return {startUrls:[{url:c.companyUrl}],maxJobsPerCompany:c.maxJobs,keywords:[],location:'',workplaceType:[],employmentType:[],postedAfter:'',enrichWithAI:false};}
function originalInput(input,c){const expected=actorInput(c);for(const [k,v]of Object.entries(expected))if(JSON.stringify(input?.[k])!==JSON.stringify(v))throw new Error('Saved run input differs from this company or listing-only settings.');return input;}
function prepareSheet(meta){
 if(!Array.isArray(meta?.sheets))throw new Error('Cannot read spreadsheet tabs.');const names=meta.sheets.map(s=>s.properties?.title);
 if(names.includes(LOCK_TAB))throw new Error('Destination is locked. Check active executions and Career Runs before clearing a stale lock and resuming.');
 const requests=[{addSheet:{properties:{title:LOCK_TAB,gridProperties:{rowCount:5,columnCount:2}}}}];
 for(const title of [BUSINESS_TAB,HISTORY_TAB,RUN_TAB])if(!names.includes(title))requests.push({addSheet:{properties:{title,gridProperties:{rowCount:MAX_EXISTING+2,columnCount:20}}}});
 return {requests};
}
function validateTable(values,headers,label){
 if(!values?.length)return [];if(headers.some((h,i)=>values[0]?.[i]!==h))throw new Error(label+' headers differ from the managed schema.');
 const rows=values.slice(1);if(rows.length>MAX_EXISTING)throw new Error(label+' exceeds 5,000 rows. Archive first.');
 const keys=new Set();for(const row of rows){const key=String(row[0]??'');if(!key||keys.has(key))throw new Error(label+' has blank or duplicate keys.');keys.add(key);}return rows;
}
function checkRun(run){if(run?.actId!==ACTOR_ID)throw new Error('Run belongs to another Actor.');if(['FAILED','ABORTED','TIMED-OUT'].includes(run.status))throw new Error('Actor run '+run.id+' ended '+run.status+'. Inspect its log.');if(!['READY','RUNNING','TIMING-OUT','ABORTING','SUCCEEDED'].includes(run.status))throw new Error('Unexpected Actor status.');return run.status==='SUCCEEDED';}
function checkDataset(meta){if(!Number.isInteger(meta.itemCount)||meta.itemCount<=0)throw new Error('Empty dataset: inspect the Actor log. Missing jobs are not proven closed.');if(meta.itemCount>MAX_DATASET)throw new Error('Dataset exceeds 1,000-row retrieval bound.');return meta.itemCount;}
const scalar=v=>typeof v==='string'?v.trim().slice(0,1500):'';
function normalize(item){
 if(!item||!scalar(item.title)||!scalar(item.companyDomain)||!scalar(item.jobId)||!scalar(item.jobUrl))return null;
 const domain=scalar(item.companyDomain).toLowerCase();if(!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(domain))return null;
 const url=scalar(item.jobUrl);if(!/^https:\/\/[a-z0-9.-]+\.[a-z]{2,}(?:\/[^\s]*)?$/i.test(url))return null;
 const id=scalar(item.jobId),key='career:'+domain+':'+id;
 return {key,id,title:scalar(item.title),name:scalar(item.companyName),domain,source:scalar(item.source),url,apply:scalar(item.applyUrl),location:scalar(item.location),remote:item.remote===true?'TRUE':item.remote===false?'FALSE':scalar(item.remote),employment:scalar(item.employmentType),posted:typeof item.postedAt==='string'&&Number.isFinite(Date.parse(item.postedAt))?item.postedAt:''};
}
function ledgerRow(ctx,status,counts={},notes=''){const {run,input,executionId}=ctx;return [run.id,status,input.startUrls?.[0]?.url??'',input.maxJobsPerCompany??'',run.startedAt??'',run.finishedAt??'',run.defaultDatasetId??'',counts.read??'',counts.rejected??'',counts.baselines??'',counts.newJobs??'',counts.updated??'',counts.historyAdded??'',counts.replayed??'',run.options?.maxTotalChargeUsd??'',run.buildNumber??'',String(executionId??''),notes];}
function planWrites(ctx,items,existing,ledger,datasetCount,history=[]){
 if(!Array.isArray(items)||items.length!==datasetCount)throw new Error('Dataset retrieval incomplete.');const c=config(ctx.config);originalInput(ctx.input,c);checkDataset({itemCount:items.length});
 const time=ctx.run.finishedAt;if(!time||!Number.isFinite(Date.parse(time)))throw new Error('Completed run timestamp missing.');
 for(const r of ledger)if(r[2]!==c.companyUrl)throw new Error('Use one company URL per spreadsheet to keep baseline semantics reliable.');
 const oldMap=new Map(existing.map((r,i)=>[String(r[0]),{row:r,index:i+2}])),histKeys=new Set(history.map(r=>String(r[0])));
 const completed=ledger.some(r=>r[0]===ctx.run.id&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(r[1]));
 for(const r of existing){if(r[17]!==c.companyUrl)throw new Error('Existing jobs belong to another company URL.');if(!Number.isFinite(Date.parse(r[13]))||Date.parse(r[13])>Date.parse(time))throw new Error('Current sheet contains invalid or newer observations.');}
 const baseline=!ledger.some(r=>r[0]!==ctx.run.id&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(r[1]));
 const unique=new Map(),counts={read:items.length,rejected:0,duplicates:0,baselines:0,newJobs:0,updated:0,historyAdded:0,replayed:0};
 for(const item of items){const n=normalize(item);if(!n){counts.rejected++;continue;}if(unique.has(n.key)){counts.duplicates++;continue;}unique.set(n.key,n);}
 if(!unique.size)throw new Error('No valid job identities; possible Actor schema drift. Nothing written.');
 const data=[{range:`'${BUSINESS_TAB}'!A1:R1`,values:[BUSINESS_HEADERS]},{range:`'${HISTORY_TAB}'!A1:M1`,values:[HISTORY_HEADERS]},{range:`'${RUN_TAB}'!A1:R1`,values:[RUN_HEADERS]}];
 let next=existing.length+2,hnext=history.length+2;
 for(const n of unique.values()){
  const old=oldMap.get(n.key),r=old?.row,hk=ctx.run.id+':'+n.key;
  if(completed&&(r?.[15]!==ctx.run.id||!histKeys.has(hk)))throw new Error('Completed run ledger disagrees with job observations. Restore destination before replay.');
  if(r?.[15]===ctx.run.id){if(!histKeys.has(hk))throw new Error('Current row lacks matching history; inspect interrupted writes.');counts.replayed++;continue;}
  if(histKeys.has(hk))throw new Error('History/current disagreement; inspect interrupted writes.');
  if(r&&Date.parse(r[13])===Date.parse(time))throw new Error('Different runs have identical observation timestamps.');
  const type=r?r[16]:baseline?'BASELINE':'NEW';const row=old?.index??next++;
  if(row>MAX_EXISTING+1||hnext>MAX_EXISTING+1)throw new Error('Observation table full. Archive first.');
  data.push({range:`'${BUSINESS_TAB}'!A${row}:R${row}`,values:[[n.key,n.id,n.title,n.name,n.domain,n.source,n.url,n.apply,n.location,n.remote,n.employment,n.posted,r?.[12]||time,time,r?.[14]||ctx.run.id,ctx.run.id,type,c.companyUrl]]});
  data.push({range:`'${HISTORY_TAB}'!A${hnext}:M${hnext}`,values:[[hk,ctx.run.id,n.key,n.id,n.title,n.name,n.location,n.remote,n.posted,time,r?'REFRESHED':type,n.url,c.companyUrl]]});
  hnext++;counts.historyAdded++;if(r)counts.updated++;else if(baseline)counts.baselines++;else counts.newJobs++;
 }
 const found=ledger.findIndex(r=>r[0]===ctx.run.id),ri=found>=0?found+2:ledger.length+2;if(ri>MAX_EXISTING+1)throw new Error('Run log full.');
 const status=counts.rejected?'PARTIAL_ROWS_REJECTED':'IMPORTED';const notes=`${counts.baselines} baseline; ${counts.newJobs} newly observed; ${counts.updated} refreshed; ${counts.replayed} replayed. First seen is not publication time; missing jobs are not assumed closed.`;
 if(!(found>=0&&['IMPORTED','PARTIAL_ROWS_REJECTED'].includes(ledger[found][1])))data.push({range:`'${RUN_TAB}'!A${ri}:R${ri}`,values:[ledgerRow(ctx,status,counts,notes)]});
 return {body:{valueInputOption:'RAW',data},summary:{status,runId:ctx.run.id,datasetId:ctx.run.defaultDatasetId,...counts,notes}};
}

return [{json:config($json)}];

